// Fichier : Main.java
// Regle importante : le nom du fichier doit correspondre au nom de la classe publique.
public class Main {
    // 'main' est le point d'entree : la methode que la JVM appelle en premier.
    public static void main(String[] args) {
        // Affiche une ligne de texte dans le terminal.
        System.out.println("Bonjour depuis Java 21 !");
    }
}
